+        if (isDisplay) {
+            sb.append("\n");
+            sb.repeat(indent, depth);
+        }
+        sb.append(close);
+        stack.pop();
+        if (!stack.isEmpty()) {
+            sb.append(delim); // Need to append delim for structures
+        }
+    }
